async function loadPoloSizesXML(url, poloId) {
    try {
        const res = await fetch(url);
        const text = await res.text();
        const xml = new DOMParser().parseFromString(text, "text/xml");
        const version = "v" + appVersion;

        if (!sizes.poloMap) sizes.poloMap = {};
        const allMaps = xml.querySelectorAll(`${version} > poloMap`);

        console.log(`Scanning XML: Found ${allMaps.length} custom polo maps.`);

        allMaps.forEach(map => {
            const mId = map.getAttribute("id");
            const mPolo = map.querySelector("polo");
            if (mPolo) {
                if (!sizes.poloMap[mId]) sizes.poloMap[mId] = {};
                const mGet = (tag) => {
                    const el = mPolo.querySelector(tag);
                    return el ? parseFloat(el.textContent) : undefined;
                };
                const mData = {
                    sprWidth: mGet("sprWidth"),
                    sprHeight: mGet("sprHeight"),
                    sprEyesH: mGet("sprEyesH"),
                    sprEyelidX: mGet("sprEyelidX"),
                    sprEyelid1Y: mGet("sprEyelid1Y"),
                    sprEyelid2Y: mGet("sprEyelid2Y"),
                    sprEyelid3Y: mGet("sprEyelid3Y"),
                    sprEyelid4Y: mGet("sprEyelid4Y"),
                    sprPupY: mGet("sprPupY"),
                    eyesTopY: mGet("eyesTopY"),
                    pupilType: mPolo.querySelector("pupilType")?.textContent || "sprite",
                    pupilW: mGet("pupilW"),
                    pupilH: mGet("pupilH"),
                    pup1Y: mGet("pup1Y"),
                    pup2Y: mGet("pup2Y"),
                    maxPupMove: mGet("maxPupMove"),
                    pupilColor: mPolo.querySelector("pupilColor")?.textContent || "#000000",
                    nudgeRight: mGet("nudgeRight"),
                    nudgeLeft: mGet("nudgeLeft"),
                    nudgeDown: mGet("nudgeDown"),
                    nudgeUp: mGet("nudgeUp")
                };
                Object.keys(mData).forEach(k => {
                    if (mData[k] !== undefined) sizes.poloMap[mId][k] = mData[k];
                });

                console.log(`Polo sizes loaded for ID ${mId}:`, mData);
            }
        });

        console.log("Checking for ID:", poloId, "in version:", version);

        let node = xml.querySelector(`${version} > poloMap[id="${String(poloId)}"] > polo`);

        if (node) {
            console.log("SUCCESS: Found custom map for ID " + poloId);
        } else {
            console.log("FAIL: Could not find poloMap for ID " + poloId + ". Falling back to version default.");
            node = xml.querySelector(`${version} > polo`);
        }

        if (!node) {
            node = xml.querySelector("default > polo");
        }

        if (!node) {
            console.warn("No polo config found, using defaults");
            return;
        }

        const get = (tag) => {
            const el = node.querySelector(tag);
            return el ? parseInt(el.textContent) : undefined;
        };

        const newVals = {
            sprWidth: get("sprWidth"),
            sprHeight: get("sprHeight"),
            sprEyesW: get("sprEyesW"),
            sprEyesH: get("sprEyesH"),
            sprEyesX: get("sprEyesX"),
            sprEyesY: get("sprEyesY"),
            sprEyelidX: get("sprEyelidX"),
            sprEyelid1Y: get("sprEyelid1Y"),
            sprEyelid2Y: get("sprEyelid2Y"),
            sprEyelid3Y: get("sprEyelid3Y"),
            sprEyelid4Y: get("sprEyelid4Y"),
            sprPupY: get("sprPupY"),
            pup1Y: get("pup1Y"),
            pup2Y: get("pup2Y"),
            eyesTopY: get("eyesTopY"),
            maxPupMove: get("maxPupMove")
        };

        if (!sizes.poloMap[poloId]) sizes.poloMap[poloId] = {};

        Object.keys(newVals).forEach(k => {
            if (newVals[k] !== undefined) {
                let isSpecific = xml.querySelector(`${version} > poloMap[id="${poloId}"]`);
                if (isSpecific) {
                    sizes.poloMap[poloId][k] = newVals[k];
                } else {
                    sizes.polo[k] = newVals[k];
                }
            }
        });

        console.log("DEBUG version:", version);
        console.log("ID being passed:", poloId);
    } catch (err) {
        console.warn("Failed to load polo sizes XML, using defaults", err);
    }
}
