            { id: "--url-img-home-titre", file: "home-titre.png", type: "root", active: app.customTitle },
            { id: "--url-img-home-version", file: "home-version.png", type: "root", active: app.customVersion },
            { id: ".waiting-picto", file: "game-picto.png", type: "class" }
