function validFormMix() {
    var h;
    var j;
    var k;
    var m;
    var q;
    var v;
    var w;
    var x;
    var y;
    var z;
    var A;
    function B() {
        TweenMax.delayedCall(1, function () {
            Spinner.reset();
            popupMixSaved();
        });
    }
    if (!(boxPopup.$popup.find(".formzone .formline input").hasClass("focused") || formProcessing)) {
        formProcessing = true;
        lock();
        h = appBrowser || true || !boxPopup.$popup.find(".formzone .bt-onofftext").hasClass("active");
        j = boxPopup.$popup.find(".formzone #input-name");
        k = boxPopup.$popup.find(".formzone #input-title");
        m = boxPopup.$popup.find(".formzone #input-dedi");
        q = j.val().substr(0, 26);
        v = k.val().substr(0, 26);
        w = m.val().substr(0, 26);
        q = cleanInputText(q);
        v = cleanInputText(v);
        w = cleanInputText(w);
        z = regexList.classic;
        x = q.replace(/ /g, "");
        y = v.replace(/ /g, "");
        A = w.replace(/ /g, "");
        if (z.test(x)) {
            invalidField(j);
        } else if (z.test(y)) {
            invalidField(k);
        } else if (z.test(A)) {
            invalidField(m);
        } else if (x === "") {
            invalidField(j);
        } else if (y === "") {
            invalidField(k);
        } else {
            deleteFocus();
            boxPopup.$popup.find(".formzone input").blur();
            z = {
                mymix: true,
                online: false,
                name: ucwords(q),
                title: ucwords(v),
                dedi: ucwords(w),
                app: app.version,
                datedb: getDateNow(),
                link: getUniqLink(),
                private: true,
                nbview: 0,
                nblike: 0,
                xml: trim(recordMix.getXML())
            };
            A = boxPopup.$popup.find(".bt.valid");
            Spinner.add(A);
            recordMix.setData(z);
            localMixObject.saveMix(z);
            mixToShare = z;
            setUserInfo({
                djname: ucwords(q)
            });
            delete XHRmemotime.mymix;
            saveMixDB(z, B);
            B();
        }
    }
}
