function checkLanguageCode(e) {
    var o = e.toLowerCase();
    if (o.indexOf("en-") > -1) {
        return "en-US";
    } else if (o.indexOf("pt-") > -1) {
        return "pt-BR";
    } else if (o.indexOf("fr-") > -1) {
        return "fr";
    } else if (o.indexOf("es-") > -1) {
        return "es";
    } else if (o.indexOf("it-") > -1) {
        return "it";
    } else if (o.indexOf("de-") > -1) {
        return "de";
    } else if (o.indexOf("cn") > -1) {
        return "zh-CN";
    } else if (o == "zh-hant" || o == "zh-hk" || o == "zh-tw") {
        return "zh-TW";
    } else if (o == "zh-hans" || o == "zh-cn") {
        return "zh-CN";
    } else if (o == "en") {
        return "en-US";
    } else if (o == "pt") {
        return "pt-BR";
    } else if (o == "zh") {
        return "zh-CN";
    } else if (o == "hi") {
        return "hi-IN";
    } else if (o == "bn") {
        return "bn-IN";
    } else if (o == "ta") {
        return "ta-IN";
    } else if (o == "te") {
        return "te-IN";
    } else if (o == "nb" || o == "nn") {
        return "no";
    } else {
        return e;
    }
}

